//! Tests for `text/template`: Go's exec_test.go tables (replayed from fixtures
//! generated by the Go toolchain) and the API tests of exec_test.go,
//! multi_test.go and the helper functions.

#[path = "../examples/common/template_harness.rs"]
mod harness;

use harness::data;
use rust_stdlib::io::fs::{DirFS, FileMode, MapFS, MapFile};
use rust_stdlib::text::template::value::{CallError, FuncError, Kind, Type, Value};
use rust_stdlib::text::template::{
    self as tt, func0, func1, func2, is_true, map_of_any, must, parse, variadic, Error, Fallible,
    FuncMap, Template, ToValue,
};
use std::collections::{BTreeMap, HashMap};

fn render<D: ToValue + ?Sized>(t: &Template, data: &D) -> String {
    let mut out = Vec::new();
    t.execute(&mut out, data).unwrap_or_else(|e| panic!("{e}"));
    String::from_utf8(out).expect("utf-8")
}

fn render_err<D: ToValue + ?Sized>(t: &Template, data: &D) -> (String, String) {
    let mut out = Vec::new();
    let e = t.execute(&mut out, data).expect_err("expected an error");
    (e.to_string(), String::from_utf8(out).expect("utf-8"))
}

fn assert_send_sync<T: Send + Sync>() {}

/// Every input of Go's exec tests (execTests, cmpTests, delimiters, missing
/// keys, panics during calls, ...) gets Go's output or Go's error text.
#[test]
fn fixtures_match_go() {
    let n = harness::replay("text.jsonl");
    assert!(n > 500, "only {n} text fixtures replayed");
}

#[test]
fn templates_are_thread_safe() {
    assert_send_sync::<Template>();
    assert_send_sync::<Value>();
    assert_send_sync::<tt::value::Type>();
}

