#[test]
#[allow(clippy::type_complexity)]
fn multi_parse() {
    let cases: &[(&str, &str, bool, &[&str], &[&str])] = &[
        ("empty", "", true, &[], &[]),
        (
            "one",
            r#"{{define "foo"}} FOO {{end}}"#,
            true,
            &["foo"],
            &[" FOO "],
        ),
        (
            "two",
            r#"{{define "foo"}} FOO {{end}}{{define "bar"}} BAR {{end}}"#,
            true,
            &["foo", "bar"],
            &[" FOO ", " BAR "],
        ),
        ("missing end", r#"{{define "foo"}} FOO "#, false, &[], &[]),
        ("malformed name", r#"{{define "foo}} FOO "#, false, &[], &[]),
    ];
    for &(name, input, ok, names, results) in cases {
        let r = Template::new("root").parse(input);
        match (r, ok) {
            (Err(e), true) => panic!("{name}: unexpected error: {e}"),
            (Ok(_), false) => panic!("{name}: expected error"),
            (Err(_), false) => continue,
            (Ok(t), true) => {
                assert_eq!(
                    t.templates().len(),
                    names.len() + 1,
                    "{name}: template count (+1 for root)"
                );
                for (n, want) in names.iter().zip(results) {
                    let sub = t
                        .lookup(n)
                        .unwrap_or_else(|| panic!("{name}: no template {n}"));
                    assert_eq!(
                        sub.tree().unwrap().root.as_ref().unwrap().to_string(),
                        *want
                    );
                }
            }
        }
    }
}

const MULTI_TEXT1: &str = "\n\t{{define \"x\"}}TEXT{{end}}\n\t{{define \"dotV\"}}{{.V}}{{end}}\n";
const MULTI_TEXT2: &str =
    "\n\t{{define \"dot\"}}{{.}}{{end}}\n\t{{define \"nested\"}}{{template \"dot\" .}}{{end}}\n";

fn run_multi_exec(template: &Template) {
    let funcs = data::std_funcs();
    let tval = data::t_val();
    let cases: &[(&str, &str, &str, Value)] = &[
        ("empty", "", "", Value::nil()),
        ("text", "some text", "some text", Value::nil()),
        ("invoke x", "{{template \"x\" .SI}}", "TEXT", tval.clone()),
        (
            "invoke x no args",
            "{{template \"x\"}}",
            "TEXT",
            tval.clone(),
        ),
        (
            "invoke dot int",
            "{{template \"dot\" .I}}",
            "17",
            tval.clone(),
        ),
        (
            "invoke dot []int",
            "{{template \"dot\" .SI}}",
            "[3 4 5]",
            tval.clone(),
        ),
        ("invoke dotV", "{{template \"dotV\" .U}}", "v", tval.clone()),
        (
            "invoke nested int",
            "{{template \"nested\" .I}}",
            "17",
            tval.clone(),
        ),
        (
            "variable declared by template",
            "{{template \"nested\" $x:=.SI}},{{index $x 1}}",
            "[3 4 5],4",
            tval.clone(),
        ),
        (
            "testFunc literal",
            "{{oneArg \"joe\"}}",
            "oneArg=joe",
            tval.clone(),
        ),
        (
            "testFunc .",
            "{{oneArg .}}",
            "oneArg=joe",
            Value::string("joe"),
        ),
    ];
    for (name, input, want, dot) in cases {
        let tmpl = template
            .associated(name)
            .funcs(&funcs)
            .parse(input)
            .expect(name);
        let mut out = Vec::new();
        tmpl.execute_value(&mut out, dot.clone())
            .unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(String::from_utf8(out).unwrap(), *want, "{name}");
    }
}

#[test]
fn multi_execute() {
    let template = Template::new("root").parse(MULTI_TEXT1).unwrap();
    template.parse(MULTI_TEXT2).unwrap();
    run_multi_exec(&template);
}

fn testdata() -> std::path::PathBuf {
    std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/template/testdata")
}

#[test]
fn parse_files_and_glob_and_fs() {
    assert!(tt::parse_files(&["DOES NOT EXIST"]).is_err());
    let dir = testdata();
    let f1 = dir.join("file1.tmpl");
    let f2 = dir.join("file2.tmpl");
    let template = Template::new("root");
    template
        .parse_files(&[f1.to_str().unwrap(), f2.to_str().unwrap()])
        .unwrap();
    run_multi_exec(&template);

    assert!(tt::parse_glob("DOES NOT EXIST").is_err());
    assert!(Template::new("error").parse_glob("[x").is_err());
    let template = Template::new("root");
    template
        .parse_glob(dir.join("file*.tmpl").to_str().unwrap())
        .unwrap();
    run_multi_exec(&template);

    let fs = DirFS::new(dir.clone());
    assert!(tt::parse_fs(&fs, &["DOES NOT EXIST"]).is_err());
    let template = Template::new("root");
    template
        .parse_fs(&fs, &["file1.tmpl", "file2.tmpl"])
        .unwrap();
    run_multi_exec(&template);
    let template = Template::new("root");
    template.parse_fs(&fs, &["file*.tmpl"]).unwrap();
    run_multi_exec(&template);

    // Files whose names are template names, with content.
    let template = Template::new("root");
    template
        .parse_files(&[
            dir.join("tmpl1.tmpl").to_str().unwrap(),
            dir.join("tmpl2.tmpl").to_str().unwrap(),
        ])
        .unwrap();
    let t = template
        .associated("test")
        .parse(r#"{{template "tmpl1.tmpl"}}{{template "tmpl2.tmpl"}}"#)
        .unwrap();
    assert_eq!(render(&t, &0i64), "template1\n\ny\ntemplate2\n\nx\n");
    let template = Template::new("root");
    template
        .parse_glob(dir.join("tmpl*.tmpl").to_str().unwrap())
        .unwrap();
    let t = template
        .associated("test")
        .parse(r#"{{template "tmpl1.tmpl"}}{{template "tmpl2.tmpl"}}"#)
        .unwrap();
    assert_eq!(render(&t, &0i64), "template1\n\ny\ntemplate2\n\nx\n");

    // An in-memory file system.
    let mut mfs = MapFS::new();
    mfs.insert(
        "a.tmpl",
        MapFile::new(&b"A{{template \"b.tmpl\"}}"[..], FileMode(0)),
    );
    mfs.insert("b.tmpl", MapFile::new(&b"B"[..], FileMode(0)));
    mfs.insert("sub/c.txt", MapFile::new(&b"C"[..], FileMode(0)));
    let t = tt::parse_fs(&mfs, &["*.tmpl"]).unwrap();
    assert_eq!(t.name(), "a.tmpl");
    assert_eq!(render(&t, &()), "AB");
    let err = tt::parse_fs(&mfs, &["[x"]).unwrap_err();
    assert_eq!(err.to_string(), "syntax error in pattern");
    let err = tt::parse_fs(&mfs, &["*.nothing"]).unwrap_err();
    assert_eq!(
        err.to_string(),
        "template: pattern matches no files: `*.nothing`"
    );
}

const CLONE_TEXT1: &str = r#"{{define "a"}}{{template "b"}}{{template "c"}}{{end}}"#;
const CLONE_TEXT2: &str = r#"{{define "b"}}b{{end}}"#;
const CLONE_TEXT3: &str = r#"{{define "c"}}root{{end}}"#;
const CLONE_TEXT4: &str = r#"{{define "c"}}clone{{end}}"#;
const CLONE_TEXT5: &str = r#"{{define "e"}}{{.Foo}}{{end}}"#;

#[test]
fn clone() {
    let root = Template::new("root").parse(CLONE_TEXT1).unwrap();
    root.parse(CLONE_TEXT2).unwrap();
    root.parse(CLONE_TEXT5).unwrap();
    root.option(&["missingkey=error"]);
    let clone = root.clone_template().unwrap();
    root.parse(CLONE_TEXT3).unwrap();
    clone.parse(CLONE_TEXT4).unwrap();
    // The clone is self-consistent.
    for t in clone.templates() {
        assert_eq!(clone.lookup(t.name()).unwrap(), t);
    }
    let mut b = Vec::new();
    root.execute_template(&mut b, "a", &0i64).unwrap();
    assert_eq!(b, b"broot");
    let mut b = Vec::new();
    clone.execute_template(&mut b, "a", &0i64).unwrap();
    assert_eq!(b, b"bclone");
    let m = map_of_any([]);
    let mut b = Vec::new();
    let root_err = root.execute_template(&mut b, "e", &m).unwrap_err();
    let clone_err = clone.execute_template(&mut b, "e", &m).unwrap_err();
    assert_eq!(clone_err.to_string(), root_err.to_string());
    assert!(clone_err.to_string().contains("map has no entry for key"));
}

#[test]
fn add_parse_tree() {
    let root = Template::new("root").parse(CLONE_TEXT1).unwrap();
    root.parse(CLONE_TEXT2).unwrap();
    let trees = parse::parse("cloneText3", CLONE_TEXT3, "", "", &[]).unwrap();
    let added = root.add_parse_tree("c", trees["c"].clone()).unwrap();
    let mut b = Vec::new();
    added.execute_template(&mut b, "a", &0i64).unwrap();
    assert_eq!(b, b"broot");
    // Issue 7032: adding to an unparsed template must not panic.
    let tmpl = Template::new("master");
    let trees = parse::parse("master", r#"{{define "master"}}{{end}}"#, "", "", &[]).unwrap();
    tmpl.add_parse_tree("master", trees["master"].clone())
        .unwrap();
}

