#[test]
fn template_lookup() {
    let t1 = Template::new("foo");
    assert!(t1.lookup("foo").is_none(), "undefined template foo");
    t1.associated("bar");
    assert!(t1.lookup("bar").is_none(), "undefined template bar");
    t1.parse(r#"{{define "foo"}}test{{end}}"#).unwrap();
    assert!(t1.lookup("foo").is_some());
}

#[test]
fn new_with_an_existing_name() {
    let t1 = Template::new("test")
        .parse(r#"{{define "test"}}foo{{end}}"#)
        .unwrap();
    let t2 = t1.associated("test");
    assert!(t1.tree().is_some(), "defined template got nil Tree");
    assert!(t2.tree().is_none(), "undefined template got a Tree");
    let mut contains_t1 = false;
    for t in t1.templates() {
        assert!(t != t2, "Templates included undefined template");
        if t == t1 {
            contains_t1 = true;
        }
    }
    assert!(contains_t1, "Templates didn't include defined template");
}

