#[test]
fn empty_template() {
    let cases: &[(&[&str], &str, &str)] = &[
        (&["x", "y"], "", "y"),
        (&[""], "once", ""),
        (&["", ""], "twice", ""),
        (&["{{.}}", "{{.}}"], "twice", "twice"),
        (
            &["{{/* a comment */}}", "{{/* a comment */}}"],
            "comment",
            "",
        ),
        (&["{{.}}", ""], "twice", ""),
    ];
    for (i, (defs, input, want)) in cases.iter().enumerate() {
        let root = Template::new("root");
        let mut m = None;
        for d in *defs {
            m = Some(root.associated(input).parse(d).unwrap());
        }
        assert_eq!(render(&m.unwrap(), input), *want, "case {i}");
    }
}

#[test]
fn issue_19294_block_replacement_does_not_depend_on_order() {
    let inlined = [
        ("stylesheet", r#"{{define "stylesheet"}}stylesheet{{end}}"#),
        ("xhtml", r#"{{block "stylesheet" .}}{{end}}"#),
    ];
    for i in 0..20 {
        let res = Template::new("title.xhtml")
            .parse(r#"{{template "xhtml" .}}"#)
            .unwrap();
        for (name, src) in inlined {
            res.associated(name).parse(src).unwrap();
        }
        assert_eq!(render(&res, &0i64), "stylesheet", "iteration {i}");
    }
}

